/*
 * A095313  Primes in whose binary expansion the number of 1-bits is <= 6 +
 *          number of 0-bits.
 * https://oeis.org/A095313
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 53, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * OEIS A095313: primes whose binary expansion has
 * 1-bits ≤ 6 + number of 0-bits.
 *
 * The sequence is generated by
 *   a(n) = the n-th prime p such that 2*popcount(p) ≤ bitlen(p) + 6.
 * The algorithm keeps a growing list of all qualifying primes in static memory
 * and generates new primes on demand by trial division against the primes
 * already found.  This runs in O(n log n) time and uses only standard C
 * allocations; it works for all builds where `seq_t` is an unsigned integer
 * type (8, 16, 32, 64 or 128 bits) or a simple integer class.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Static data used to cache the sequence and to generate new primes.  */
static seq_t  *qcache    = NULL;     /* array of qualifying primes      */
static size_t qcap      = 0;         /* capacity of qcache             */
static size_t qlen      = 0;         /* number of elements in qcache   */

static uint64_t *pl     = NULL;      /* list of all primes found so far */
static size_t  pl_cap   = 0;         /* capacity of pl                 */
static size_t  pl_len   = 0;         /* number of primes in pl         */

static uint64_t next_candidate = 3;  /* next odd number to test        */

/* Expand the array `arr` of type `T` when it is full.  */
#define GROW_IF_FULL(arr, cap, len, type)            \
    do {                                            \
        if ((len) == (cap)) {                       \
            size_t new_cap = (cap) ? (cap) << 1 : 32; \
            type *tmp = (type*)realloc((arr), new_cap * sizeof(type)); \
            if (!tmp) exit(1);                      \
            (arr) = tmp;                            \
            (cap) = new_cap;                        \
        }                                           \
    } while (0)

/* Test if a prime satisfies the bitcount inequality.  */
static inline bool qualifies(uint64_t p)
{
    unsigned ones   = __builtin_popcountll(p);
    unsigned bitlen = 64 - __builtin_clzll(p);
    return ((ones << 1) <= (bitlen + 6));
}

/* Generate primes up to and including `limit`, adding qualifying ones
 * to the cache.  The function stops as soon as `qlen` reaches `need`.  */
static void generate_to(size_t need)
{
    /* Initialise prime list with the first prime 2 if not yet done.  */
    if (pl_len == 0) {
        GROW_IF_FULL(pl, pl_cap, pl_len, uint64_t);
        pl[pl_len++] = 2;
        /* 2 is always qualifying (popcount=1, bitlen=2).  */
        GROW_IF_FULL(qcache, qcap, qlen, seq_t);
        qcache[qlen++] = (seq_t)2;
        /* next candidate will be 3.  */
    }

    /* Generate further primes until we have `need` qualifying terms.  */
    while (qlen < need) {
        uint64_t p = next_candidate;
        /* primality test by trial division using previously found primes.  */
        bool is_prime = true;
        for (size_t i = 0; i < pl_len && pl[i] * pl[i] <= p; ++i) {
            if (p % pl[i] == 0) { is_prime = false; break; }
        }
        if (is_prime) {
            /* store the new prime */
            GROW_IF_FULL(pl, pl_cap, pl_len, uint64_t);
            pl[pl_len++] = p;
            if (qualifies(p)) {
                GROW_IF_FULL(qcache, qcap, qlen, seq_t);
                qcache[qlen++] = (seq_t)p;
            }
        }
        next_candidate += 2;   /* only odd numbers need to be checked */
    }
}

/* Ensure that at least `n` terms are available in the cache.  */
static void ensure_terms(size_t n)
{
    if (qlen < n) generate_to(n);
}

/* Main sequence function.  */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* out of bounds */
    ensure_terms((size_t)n);
    return qcache[n - 1];
}
